create table public.failure_events (id uuid primary key default gen_random_uuid(), asset_id uuid not null references public.assets(id) on delete restrict, reported_by uuid references auth.users(id) on delete set null, occurred_at timestamptz not null, detected_at timestamptz, restored_at timestamptz, status public.failure_status not null default 'open', failure_mode text, failure_cause text, symptom text, corrective_action text, downtime_minutes integer check(downtime_minutes is null or downtime_minutes>=0), production_loss text, maximo_work_order_id text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.reliability_projects (id uuid primary key default gen_random_uuid(), site_id uuid references public.sites(id) on delete set null, asset_id uuid references public.assets(id) on delete set null, name text not null, description text, status public.project_status not null default 'planned', owner_id uuid references auth.users(id) on delete set null, start_date date, target_date date, completed_date date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.corrective_actions (id uuid primary key default gen_random_uuid(), project_id uuid references public.reliability_projects(id) on delete cascade, failure_event_id uuid references public.failure_events(id) on delete cascade, title text not null, description text, owner_id uuid references auth.users(id) on delete set null, due_date date, completed_at timestamptz, status text not null default 'open', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.site_visits (id uuid primary key default gen_random_uuid(), site_id uuid not null references public.sites(id) on delete cascade, visit_date date not null, purpose text, summary text, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.notes (id uuid primary key default gen_random_uuid(), site_id uuid references public.sites(id) on delete set null, asset_id uuid references public.assets(id) on delete set null, failure_event_id uuid references public.failure_events(id) on delete set null, project_id uuid references public.reliability_projects(id) on delete set null, visit_id uuid references public.site_visits(id) on delete set null, author_id uuid references auth.users(id) on delete set null, note_type public.note_type not null default 'general', title text, body text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.documents (id uuid primary key default gen_random_uuid(), site_id uuid references public.sites(id) on delete set null, asset_id uuid references public.assets(id) on delete set null, project_id uuid references public.reliability_projects(id) on delete set null, failure_event_id uuid references public.failure_events(id) on delete set null, name text not null, document_type public.document_type not null default 'other', description text, storage_path text, source_system text, source_reference text, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.document_versions (id uuid primary key default gen_random_uuid(), document_id uuid not null references public.documents(id) on delete cascade, version_label text not null, storage_path text not null, file_size_bytes bigint, checksum text, page_count integer, revision_date date, uploaded_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), unique(document_id,version_label));
